<?php require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../config/session.php';require_once __DIR__.'/../../config/functions.php';require_once __DIR__.'/../../config/auth.php';requireAdmin();if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);if($id){$stmt=$pdo->prepare('SELECT COUNT(*) FROM enrollments WHERE course_id=?');$stmt->execute([$id]);if((int)$stmt->fetchColumn()===0){$stmt=$pdo->prepare('DELETE FROM courses WHERE id=?');$stmt->execute([$id]);}else{$stmt=$pdo->prepare("UPDATE courses SET status='inactive' WHERE id=?");$stmt->execute([$id]);}}}header('Location: index.php');exit;?>
